import {orderTasks,hasUnread} from './admin-order-attention.mjs';
import {captureWarning,appendCaptureWarning} from './admin-capture-warning.mjs';
import {matchesOrder} from './order-search.mjs';
import {appendOrderSummaryInfo,appendOrderSummaryState,assembleOrderSummaryCard} from './admin-order-summary.mjs?v=capture-warning-1';
import {mockupsForPfOrder,appendMockupOverview} from './admin-mockups.mjs?v=4';
import {nextStep,isTestOrder,dateTime,paymentLabel} from './admin-order-state.mjs';
export function workQueue(orders,checkouts,mailRows=[]){return orders.filter(o=>!isTestOrder(o,checkouts.find(c=>c.id===o.checkoutId))).map(order=>{const checkout=checkouts.find(c=>c.id===order.checkoutId),[owner,next]=nextStep(order,checkout,mailRows),blockers=[...(order.attention?.finance?.summary?.problems||checkout?.finance?.problems||[]),...(order.proofIntakeProblems||[])];
 const paymentWarning=captureWarning(checkout);if(paymentWarning)blockers.push(paymentWarning.title);
 if(['needs_attention','needs_reconciliation'].includes(order.status))blockers.push(order.pfStatusInformation||'Afklar PF-status og hændelseslog.');
 if(checkout&&['authorization_expired','capture_reconciliation','payment_failed'].includes(checkout.status))blockers.push(paymentLabel(checkout));
 if(order.lines?.some(l=>l.decorations?.length)&&!mockupsForPfOrder(checkout,order).length)blockers.push('Kontrollér designvisning og mockups på ordren.');
 if(['shipped','partially_shipped'].includes(order.status)&&!order.shipment?.trackingDetails?.some(t=>t.trackingURL))blockers.push('Trackinglink mangler.');
 return {order,checkout,owner,next,tasks:orderTasks(order,checkout,{shipments:mailRows.filter(m=>m.orderId===order.id),...order.attention}),blockers,bucket:order.deliveryConfirmation?'orders':['shipped','partially_shipped'].includes(order.status)?'deliveries':['approval_recorded','processing','confirmed'].includes(order.status)?'production':['awaiting_proof','proof_received','revision_requested','approval_pending_pf'].includes(order.status)?'proofs':'orders'};});}
const pendingCheckout=c=>['authorized','capture_reconciliation'].includes(c.status)||(c.paymentProvider==='bank_transfer'&&['awaiting_bank_payment','paid'].includes(c.status));
const checkoutBlocked=c=>c.pfHandoff?.status!=='awaiting_review'&&(c.paymentProvider!=='bank_transfer'||c.pfHandoff?.status==='blocked');
const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
function renderQueueContents(container,orders,checkouts,view='overview',mailRows=[],query=''){const rows=workQueue(orders,checkouts,mailRows).filter(r=>matchesOrder(query,{checkout:r.checkout,orders:[r.order]})),active=rows.filter(r=>r.order.status!=='cancelled');
 if(['overview','actions','blocked','deliveries'].includes(view))for(const mail of mailRows.filter(m=>!orders.some(o=>o.id===m.orderId)&&['review','blocked','failed','uncertain'].includes(m.status)&&matchesOrder(query,{extra:[m.orderId,m.to,m.subject,m.error]}))){const card=el('article'),link=el('a','Åbn besked');link.href='/admin/pf-orders#order='+mail.orderId+'&tab=documents';card.append(el('strong','Mail kræver handling'),el('p',mail.error||mail.to),link);container.append(card);}


 const filtered=active.filter(r=>view==='overview'||view==='actions'?r.tasks.length||r.blockers.length:view==='blocked'?(r.blockers.length||r.tasks.some(t=>t.error)):r.bucket===view);
 for(const r of filtered){const card=el('article');card.className='order-summary-card';const gallery=el('div'),info=el('div'),state=el('div');appendMockupOverview(gallery,mockupsForPfOrder(r.checkout,r.order),{decorated:r.order.lines?.some(l=>l.decorations?.length)});appendOrderSummaryInfo(info,{checkout:r.checkout,orders:[r.order],lines:r.order.lines});const dispatchCells=appendOrderSummaryState(state,r.checkout,[r.order]);if(hasUnread(r.order))info.append(Object.assign(el('span','Nyt siden sidst'),{className:'attention-new'}));for(const task of r.tasks){const link=el('a',task.title);link.className='attention-task-link'+(task.error?' attention-error':'');link.href='/admin/pf-orders#order='+encodeURIComponent(r.order.id)+'&tab='+task.tab;state.append(link);}for(const issue of r.blockers)if(issue!==captureWarning(r.checkout)?.title&&!r.next.includes(issue))state.append(el('p',issue));const open=el('a','Åbn ordre');open.className='action light';open.href='/admin/pf-orders#order='+encodeURIComponent(r.order.id);(dispatchCells.get(r.order)||state).append(open);assembleOrderSummaryCard(card,gallery,info,state);container.append(card);}
 if(['overview','actions','blocked'].includes(view))for(const c of checkouts.filter(c=>!c.adminTest&&!orders.some(o=>o.checkoutId===c.id)&&pendingCheckout(c)&&(view!=='blocked'||checkoutBlocked(c))&&matchesOrder(query,{checkout:c}))){const p=el('div'),a=el('a','Åbn ordre og betalingsdetaljer');a.href='/admin#orders';a.onclick=()=>sessionStorage.setItem('smerch-review-checkout',c.id);p.append(document.createTextNode('Ordre uden PF-tilknytning: '+(c.shipping?.name||c.id)+' · '+(c.pfHandoff?.reason||paymentLabel(c))+' '),a);appendCaptureWarning(p,c);container.append(p);}
 if(!container.children.length)container.append(el('p',query.trim()?'Ingen ordrer matcher din søgning.':({proofs:'Ingen korrekturer i denne visning.',production:'Ingen ordrer i produktion.',deliveries:'Ingen registrerede leveringer.',blocked:'Ingen blokeringer registreret.'}[view]||'Ingen ordrer kræver din handling lige nu.')));
}
const searches=new Map();
export function renderWorkQueue(container,orders,checkouts,view='overview',mailRows=[]){
 const tools=el('div'),search=el('input'),list=el('div');tools.className='order-tools';search.type='search';search.placeholder='Søg kunde, produkt eller ordrenummer';search.setAttribute('aria-label','Søg ordrer');search.value=searches.get(view)||'';tools.append(search);container.append(tools,list);
 const render=()=>{list.replaceChildren();renderQueueContents(list,orders,checkouts,view,mailRows,search.value);};search.oninput=()=>{searches.set(view,search.value);render();};render();
}

export function queueCounts(orders,checkouts,mailRows=[]){const rows=workQueue(orders,checkouts,mailRows).filter(r=>r.order.status!=='cancelled'),actions=new Set(rows.filter(r=>r.tasks.length||r.blockers.length).map(r=>r.order.id)),blocked=new Set(rows.filter(r=>r.blockers.length||r.tasks.some(t=>t.error)).map(r=>r.order.id));for(const m of mailRows.filter(m=>!orders.some(o=>o.id===m.orderId)&&['review','blocked','failed','uncertain'].includes(m.status))){actions.add(m.orderId);if(['blocked','failed','uncertain'].includes(m.status))blocked.add(m.orderId);}const unlinked=checkouts.filter(c=>!c.adminTest&&!orders.some(o=>o.checkoutId===c.id)&&pendingCheckout(c));for(const c of unlinked){actions.add(c.id);if(checkoutBlocked(c))blocked.add(c.id);}return {overview:actions.size,orders:new Set(rows.map(r=>r.order.checkoutId||r.order.id)).size+unlinked.length,proofs:rows.filter(r=>r.bucket==='proofs').length,production:rows.filter(r=>r.bucket==='production').length,deliveries:rows.filter(r=>r.bucket==='deliveries').length,blocked:blocked.size};}
